r.append(3)
assert p == [1, 2]  # independiente de patch

# target no-objeto -> {}
assert apply_merge_patch(5, {"a": 1}) == {"a": 1}
assert apply_merge_patch(None, {"a": 1}) == {"a": 1}

# null elimina
t = {"a": 1, "b": 2}
r = apply_merge_patch(t, {"b": None, "c": 3})
assert r == {"a": 1, "c": 3}
assert t == {"a": 1, "b": 2}  # target no mutado

# recursivo anidado
t = {"x": {"y": 1, "z": 2}}
r = apply_merge_patch(t, {"x": {"z": None, "w": 9}})
assert r == {"x": {"y": 1, "w": 9}}
assert t == {"x": {"y": 1, "z": 2}}

# arrays se reemplazan completos
t = {"arr": [1, 2, 3]}
r = apply_merge_patch(t, {"arr": [9]})
assert r == {"arr": [9]}
assert t == {"arr": [1, 2, 3]}

# independencia: mutar resultado no afecta target
t = {"k": {"v": [1]}}
r = apply_merge_patch(t, {"k": {"v": [1]}})
r["k"]["v"].append(2)
assert t == {"k": {"v": [1]}}

# patch vacio
assert apply_merge_patch({"a": 1}, {}) == {"a": 1}

# patch primitiva nula
assert apply_merge_patch({"a": 1}, None) is None

print("OK")
